 a=json.loads((P/('raw/game-'+gid+'.json')).read_text());secondary.append({'gameId':gid,'date':a['game']['gameEt'][:10],'arenaId':aid,'status':'primary-source-special-fixture-candidate','sourceUrl':a['url'],'rawPath':a['rawPath'],'bodySha256':a['bodySha256'],'notes':note})
